/**
 * @payrun/api-client: the service contracts as TypeScript types (generated by
 * openapi-typescript from services/<svc>/openapi.json; run `pnpm generate`) plus
 * openapi-fetch client factories. The BFF is the only consumer (web LLD §1.3).
 */
import createClient, { type Client, type ClientOptions } from "openapi-fetch";

import type {
  components as IdentityComponents,
  operations as IdentityOperations,
  paths as IdentityPaths,
} from "./generated/identity";
import type {
  components as PayrollComponents,
  operations as PayrollOperations,
  paths as PayrollPaths,
} from "./generated/payroll";

export type { IdentityComponents, IdentityOperations, IdentityPaths };
export type { PayrollComponents, PayrollOperations, PayrollPaths };

/** Component schemas by name, e.g. `IdentitySchemas["SessionUser"]`. */
export type IdentitySchemas = IdentityComponents["schemas"];
export type PayrollSchemas = PayrollComponents["schemas"];

export type IdentityClient = Client<IdentityPaths>;
export type PayrollClient = Client<PayrollPaths>;

/** An openapi-fetch client over the identity contract. */
export function createIdentityClient(options: ClientOptions): IdentityClient {
  return createClient<IdentityPaths>(options);
}

/** An openapi-fetch client over the payroll contract. */
export function createPayrollClient(options: ClientOptions): PayrollClient {
  return createClient<PayrollPaths>(options);
}
